  VALUES (?prop ?p ?ps ?psv) { ("P569" p:P569 ps:P569 psv:P569) ("P570" p:P570 ps:P570 psv:P570) ("P53" p:P53 ps:P53 psv:P53) }
  ?item ?p ?st . ?st wikibase:rank ?rank ; ?ps ?value .
  FILTER(?rank != wikibase:DeprecatedRank)
  OPTIONAL { ?st ?psv [ wikibase:timeValue ?at ; wikibase:timePrecision ?atPrec ; wikibase:timeCalendarModel ?atCal ] . }
  OPTIONAL { ?st pqv:P580 [ wikibase:timeValue ?start ; wikibase:timePrecision ?startPrec ; wikibase:timeCalendarModel ?startCal ] . }
  OPTIONAL { ?st pqv:P582 [ wikibase:timeValue ?end ; wikibase:timePrecision ?endPrec ; wikibase:timeCalendarModel ?endCal ] . }
  OPTIONAL { ?st pq:P5102 ?nature . }
}
